export type KartPainel = { kart: string; frota: 'LIGHT' | 'SUPER' | null; fora: boolean; ocupado: boolean };
export type PilotoPainel = {
  indice: number; nome: string; customerId: string | null; kartAtual: string; excecoes: string[]; pesoKg: number | null; situacao: string; motivo: string | null; lastroConferido: boolean;
  lastro: { lastroKg: number; pecas5: number; pecas2_5: number; finalKg: number; metaKg: number } | null;
};
export type Atribuicao = { customerId: string | null; nome: string; kart: string };

export const podeSortear = (p: PilotoPainel) => p.situacao === 'ELEGIVEL' || p.situacao === 'SEM_VINCULO';

/** Sorteia os pilotos entre os karts livres, evitando repetir kart já usado pelo piloto quando dá. */
export function sortear(pilotos: PilotoPainel[], livres: string[], aleatorio: () => number = Math.random): { atribuicoes: Atribuicao[]; semKart: string[] } {
  const baralho = [...livres];
  for (let i = baralho.length - 1; i > 0; i--) {
    const j = Math.floor(aleatorio() * (i + 1));
    [baralho[i], baralho[j]] = [baralho[j], baralho[i]];
  }
  const atribuicoes: Atribuicao[] = [];
  const semKart: string[] = [];
  // quem tem mais restrições escolhe primeiro
  for (const p of [...pilotos].sort((a, b) => b.excecoes.length - a.excecoes.length)) {
    if (!baralho.length) { semKart.push(p.nome); continue; }
    const pos = baralho.findIndex((k) => !p.excecoes.includes(k));
    const [kart] = baralho.splice(pos >= 0 ? pos : 0, 1);
    atribuicoes.push({ customerId: p.customerId, nome: p.nome, kart });
  }
  return { atribuicoes, semKart };
}

export const kartsLivres = (karts: KartPainel[], frota: 'LIGHT' | 'SUPER' | null) => karts.filter((k) => !k.fora && !k.ocupado && (!frota || k.frota === frota)).map((k) => k.kart);
export const novoId = () => `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 12)}`;
